// Integer Promotion: char operands are promoted to int
char a = 5;
char b = 10;
// Result type of (a + b) is int
_Static_assert(sizeof(a + b) == sizeof(int), "Char math promotes to int");

// Usual Arithmetic Conversions: Mixed types
int i = 10;
float f = 5.5f;
// Expression (i * f) result type is float
float res_f = i * f;
double d = 2.0;
// Expression (res_f + d) result type is double
double res_d = res_f + d;

// Conditional Expression (Ternary) Result Type
int zero = 0;
long L = 100L;
// Result type is common type of the two alternatives (long)
long res_l = (zero == 0) ? L : zero;
// If types conflict, promotion follows arithmetic rules
long result_float = (1 ? 5.0f : 10L); // Result is float, then assigned to long
